// URL da bandeira (flagcdn) ou '' — Windows não renderiza emoji de bandeira.
// Tenta o ISO-2 do emoji do FLAGS; se faltar, usa o ISO do teamCode.
function flagSrc(team) {
  // Nações do Reino Unido: emoji é 🇬🇧 (UK), mas flagcdn tem as subdivisões.
  var OVERRIDE = { 'Escócia':'gb-sct', 'Inglaterra':'gb-eng', 'País de Gales':'gb-wls', 'Irlanda do Norte':'gb-nir',
                   'RD Congo':'cd' };  // entrada legada vinha com emoji vazio
  if (OVERRIDE[team]) return 'https://flagcdn.com/'+OVERRIDE[team]+'.svg';
  var code = '';
  var e = FLAGS[team] || '';
  if (e) {
    var cp = Array.from(e).map(function(c){ return c.codePointAt(0); });
    if (cp.length >= 2 && cp[0] >= 0x1F1E6)
      code = String.fromCharCode(cp[0]-0x1F1E6+65) + String.fromCharCode(cp[1]-0x1F1E6+65);
  }
  if (!code) { var tc = teamCode(team); if (/^[A-Z]{2}$/.test(tc)) code = tc; }
  return code ? 'https://flagcdn.com/'+code.toLowerCase()+'.svg' : '';
}

// Bandeira inline (acompanha o tamanho da fonte). '' se não houver.
function flag(team) {
  var s = flagSrc(team);
  return s ? '<img src="'+s+'" alt="'+team+'" loading="lazy" '+
    'style="height:1em;width:auto;vertical-align:-0.15em;display:inline-block;border-radius:2px;box-shadow:0 0 1px rgba(0,0,0,.3);">' : '';
}

// Bandeira retangular natural (sem cortar), altura fixa. Fallback = badge c/ sigla.
function teamFlag(team, h) {
  var s = flagSrc(team);
  if (s) return '<img src="'+s+'" alt="'+team+'" loading="lazy" '+
    'style="height:'+h+';width:auto;display:inline-block;vertical-align:middle;border-radius:3px;box-shadow:0 0 2px rgba(0,0,0,.35);">';
  return '<span style="display:inline-flex;align-items:center;justify-content:center;height:'+h+';min-width:'+h+';padding:0 4px;'+
    'background:#1B2B6B;color:white;border-radius:3px;font-size:.55rem;font-weight:800;">'+teamCode(team)+'</span>';
}

// 2-letter country code for team buttons
function teamCode(team) {
  var codes = {
    'Brasil':'BR','Argentina':'AR','França':'FR','Inglaterra':'GB','Espanha':'ES',
    'Alemanha':'DE','Portugal':'PT','Itália':'IT','Holanda':'NL','Bélgica':'BE',
    'Uruguai':'UY','Colômbia':'CO','México':'MX','Estados Unidos':'US','Japão':'JP',
    'República da Coreia':'KR','Marrocos':'MA','Senegal':'SN','Croácia':'HR',
    'Suíça':'CH','Polônia':'PL','Turquia':'TR','Canadá':'CA','Austrália':'AU',
    'Equador':'EC','Peru':'PE','Chile':'CL','Sérvia':'RS','Noruega':'NO',
    'Irã':'IR','Egito':'EG','Nova Zelândia':'NZ','Áustria':'AT',
    'Costa do Marfim':'CI','Curaçau':'CW','Suécia':'SE','Tunísia':'TN',
    'Gana':'GH','Panamá':'PA','Haiti':'HT','Escócia':'GB','Bósnia e Herzegovina':'BA',
    'Catar':'QA','Uzbequistão':'UZ','República Tcheca':'CZ','África do Sul':'ZA',
    'Jordânia':'JO','Argélia':'DZ','Iraque':'IQ','Rep. D. Congo':'CD',
    'República Democrática do Congo':'CD','Cabo Verde':'CV','Paraguai':'PY',
    'Arábia Saudita':'SA','Costa Rica':'CR','Jamaica':'JM','Honduras':'HN',
    'Venezuela':'VE','Camarões':'CM'
  };
  if (codes[team]) return codes[team];
  // Fallback: first letters of words
  return team.split(' ').filter(function(w){return w.length>2;}).map(function(w){return w[0];}).join('').substring(0,3).toUpperCase() || team.substring(0,2).toUpperCase();
}

// ─── PHASE MULTIPLIERS ───────────────────────────────────────────────────────
const MULTIPLIERS = {
  round_of_32: 1.0,
  groups: 1, round_of_16: 1.2, quarterfinals: 1.5, semifinals: 2, third_place: 1.5, final: 3
};

// ─── SCORING ENGINE ──────────────────────────────────────────────────────────
const Scoring = {
  calculate(bet, result) {
    const bh = parseInt(bet.home_score), ba = parseInt(bet.away_score);
    const rh = parseInt(result.home_score), ra = parseInt(result.away_score);
    let pts = 0, breakdown = [];

    // Placar exato: +15
    if (bh === rh && ba === ra) {
      pts += 15;
      breakdown.push({ label: 'Placar exato', pts: 15 });
      // Se acertou placar exato, já inclui vencedor e saldo
    } else {
      // Acertou vencedor/empate: +5
      const betWinner = bh > ba ? 'H' : (ba > bh ? 'A' : 'D');
      const resWinner = rh > ra ? 'H' : (ra > rh ? 'A' : 'D');
      if (betWinner === resWinner) {
        pts += 5;
        breakdown.push({ label: betWinner === 'D' ? 'Acertou empate' : 'Acertou vencedor', pts: 5 });
      }

      // Saldo de gols: +3
      if ((bh - ba) === (rh - ra)) {
        pts += 3;
        breakdown.push({ label: 'Saldo de gols', pts: 3 });
      }

      // Gols de um time: +2
      if (bh === rh || ba === ra) {
        pts += 2;
        breakdown.push({ label: 'Gols de um time', pts: 2 });
      }
    }

    const mult = MULTIPLIERS[result.phase] || 1;
    const total = Math.round(pts * mult);
    return { base: pts, multiplier: mult, total, breakdown };
  },

  calculateSpecials(specials, finalResults) {
    let pts = 0;
    if (!finalResults) return 0;
    if (specials.champion === finalResults.champion) pts += 50;
    if (specials.runner_up === finalResults.runner_up) pts += 25;
    if (specials.third === finalResults.third) pts += 15;
    if (specials.qualified && finalResults.qualified) {
      const correct = specials.qualified.filter(t => finalResults.qualified.includes(t));
      pts += correct.length * 5;
    }
    return pts;
  },

  // Ícone por fonte de ponto (labels vêm de calculate().breakdown)
  _srcIcon(label) {
    return {'Placar exato':'🎯','Acertou vencedor':'✅','Acertou empate':'🤝','Saldo de gols':'📊','Gols de um time':'⚽'}[label] || '•';
  },

  // HTML com a FONTE de cada ponto + base × multiplicador = total (+ bônus da fase).
  // sc = objeto retornado por Scoring.calculate. Retorna '' se não pontuou.
  breakdownHtml(sc) {
    if (!sc || !sc.breakdown || !sc.breakdown.length) return '';
    const mult = sc.multiplier || 1;
    const chip = (bg, color, txt) => '<span style="background:'+bg+';color:'+color+';border-radius:6px;padding:1px 7px;font-weight:700;white-space:nowrap;">'+txt+'</span>';
    let h = '<div style="display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:.64rem;color:#5A6385;line-height:1.6;">';
    h += sc.breakdown.map(c => chip('#EEF0F6','#2D3557', Scoring._srcIcon(c.label)+' '+c.label+' +'+c.pts)).join('');
    if (mult > 1) {
      h += '<span style="color:#9CA3BF;">= '+sc.base+'</span>';
      h += chip('rgba(124,58,237,.12)','#7C3AED','× '+mult+' = '+sc.total);
      h += '<span style="color:#7C3AED;font-weight:800;white-space:nowrap;">🔥 +'+(sc.total - sc.base)+' bônus</span>';
    } else {
      h += chip('rgba(34,197,94,.12)','#16A34A','= '+sc.total+' pts');
    }
    h += '</div>';
    return h;
  },

  // Versão texto (p/ tooltips title="").
  breakdownText(sc) {
    if (!sc || !sc.breakdown || !sc.breakdown.length) return '0 pts';
    const mult = sc.multiplier || 1;
    let t = sc.breakdown.map(c => c.label+' +'+c.pts).join(', ');
    if (mult > 1) t += ' = base '+sc.base+' × '+mult+' = '+sc.total+' (+'+(sc.total - sc.base)+' bônus)';
    else t += ' = '+sc.total+' pts';
    return t;
  }
};

// ─── ODDS (Polymarket) ───────────────────────────────────────────────────────
// Probabilidade de mercado por jogo. Série soccer-fifwc (id 11433), markets
// moneyline 3-way (Time1 win / Draw / Time2 win). Público, sem auth, CORS ok.
const Odds = {
  SERIES_ID: 11433,
  CACHE_KEY: 'bolao_odds_cache',
  TTL: 10 * 60 * 1000,
  _index: null,
  _loading: null,

  _nameIso: {
    ghana:'GH', panama:'PA', uzbekistan:'UZ', colombia:'CO',
    czechia:'CZ', czechrepublic:'CZ', southafrica:'ZA', switzerland:'CH',
    bosniaherzegovina:'BA', bosniaandherzegovina:'BA', canada:'CA', qatar:'QA',
    mexico:'MX', korearepublic:'KR', southkorea:'KR', republicofkorea:'KR',
    unitedstates:'US', usa:'US', unitedstatesofamerica:'US', australia:'AU',
    scotland:'GB', morocco:'MA', brazil:'BR', haiti:'HT',
    turkiye:'TR', turkey:'TR', paraguay:'PY', netherlands:'NL', sweden:'SE',
    germany:'DE', cotedivoire:'CI', ivorycoast:'CI', ecuador:'EC', curacao:'CW',
    tunisia:'TN', japan:'JP', spain:'ES', saudiarabia:'SA', england:'GB',
    croatia:'HR', argentina:'AR', france:'FR', portugal:'PT', italy:'IT',
    belgium:'BE', uruguay:'UY', senegal:'SN', poland:'PL', peru:'PE', chile:'CL',
    serbia:'RS', norway:'NO', iran:'IR', iranislamicrepublic:'IR', egypt:'EG',
    newzealand:'NZ', austria:'AT', algeria:'DZ', iraq:'IQ',
    drcongo:'CD', democraticrepublicofthecongo:'CD', congodr:'CD',
    capeverde:'CV', caboverde:'CV', costarica:'CR', jamaica:'JM', honduras:'HN',
    venezuela:'VE', cameroon:'CM', jordan:'JO'
  },

  iso(name) {
    if (!name) return '';
    var n = String(name).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z]/g, '');
    return this._nameIso[n] || '';
  },

  pairKey(a, b) { return [a, b].sort().join('|'); },

  // {home,draw,away} em % inteiros (orientado ao game), ou null se sem dado.
  get(game) {
    if (!this._index || !game || game.tbd) return null;
    var ha = teamCode(game.home), aa = teamCode(game.away);
    if (!/^[A-Z]{2}$/.test(ha) || !/^[A-Z]{2}$/.test(aa)) return null;
    var e = this._index[this.pairKey(ha, aa)];
    if (!e) return null;
    var homeP = (e.isoHome === ha) ? e.pHome : e.pAway;
    var awayP = (e.isoHome === ha) ? e.pAway : e.pHome;
    var sum = homeP + e.pDraw + awayP;
    if (!(sum > 0)) return null;
    return {
      home: Math.round(homeP / sum * 100),
      draw: Math.round(e.pDraw / sum * 100),
      away: Math.round(awayP / sum * 100)
    };
  },

  load(force) {
    var self = this;
    if (this._loading) return this._loading;
    if (!force) {
      try {
        var raw = localStorage.getItem(this.CACHE_KEY);
        if (raw) {
          var c = JSON.parse(raw);
          if (c && c.index && (Date.now() - c.t) < this.TTL) { this._index = c.index; return Promise.resolve(this._index); }
        }
      } catch (e) {}
    }
    this._loading = this._fetch().then(function(idx) { self._index = idx; self._loading = null; return idx; })
      .catch(function() { self._loading = null; return self._index; });
    return this._loading;
  },

  _fetch() {
    var self = this;
    var url = 'https://gamma-api.polymarket.com/events?series_id=' + this.SERIES_ID + '&closed=false&limit=200';
    return fetch(url).then(function(res) {
      if (!res.ok) throw new Error('odds http ' + res.status);
      return res.json();
    }).then(function(events) {
      var index = {};
      (events || []).forEach(function(ev) {
        // Pula mercados derivados (Halftime Result, etc.) — só o confronto "X vs. Y".
        if (String(ev.title || '').indexOf(' - ') >= 0) return;
        var teams = [], drawP = null;
        (ev.markets || []).forEach(function(m) {
          var prices = m.outcomePrices;
          if (typeof prices === 'string') { try { prices = JSON.parse(prices); } catch (e) { prices = null; } }
          if (!prices || !prices.length) return;
          var pYes = parseFloat(prices[0]);
          if (!(pYes >= 0)) return;
          var label = ((m.groupItemTitle || '') + ' ' + (m.question || '')).toLowerCase();
          if (label.indexOf('draw') >= 0) drawP = pYes;
          else teams.push({ name: m.groupItemTitle || '', p: pYes });
        });
        if (teams.length !== 2 || drawP == null) return;
        var iso0 = self.iso(teams[0].name), iso1 = self.iso(teams[1].name);
        if (!iso0 || !iso1 || iso0 === iso1) return;
        index[self.pairKey(iso0, iso1)] = { isoHome: iso0, pHome: teams[0].p, pAway: teams[1].p, pDraw: drawP };
      });
      try { localStorage.setItem(self.CACHE_KEY, JSON.stringify({ t: Date.now(), index: index })); } catch (e) {}
      return index;
    });
  },

  // Barra completa para cards de palpite. '' se tbd.
  barHtml(game) {
    if (!game || game.tbd) return '';
    var o = this.get(game);
    if (!o) {
      return '<div style="font-size:.6rem;color:#C2C7D6;text-align:center;font-weight:600;margin:0 0 10px;">Chances de mercado: —</div>';
    }
    var h = '<div title="Probabilidade implícita do mercado (Polymarket)" style="margin:0 0 12px;">';
    h += '<div style="display:flex;height:7px;border-radius:4px;overflow:hidden;background:#EEF0F6;">';
    h += '<div style="width:' + o.home + '%;background:#1B2B6B;"></div>';
    h += '<div style="width:' + o.draw + '%;background:#9CA3BF;"></div>';
    h += '<div style="width:' + o.away + '%;background:#C0392B;"></div>';
    h += '</div>';
    h += '<div style="display:flex;justify-content:space-between;font-size:.6rem;font-weight:700;color:#5A6385;margin-top:3px;">';
    h += '<span style="color:#1B2B6B;">' + o.home + '%</span>';
    h += '<span>Empate ' + o.draw + '%</span>';
    h += '<span style="color:#C0392B;">' + o.away + '%</span>';
    h += '</div></div>';
    return h;
  },

  // Mini barra para listas densas (dashboard). '' se sem dado.
  miniHtml(game) {
    var o = this.get(game);
    if (!o) return '';
    var h = '<div title="Chances de mercado (Polymarket): ' + o.home + '% / empate ' + o.draw + '% / ' + o.away + '%" ';
    h += 'style="display:flex;height:4px;border-radius:3px;overflow:hidden;background:#EEF0F6;margin-top:4px;max-width:180px;">';
    h += '<div style="width:' + o.home + '%;background:#1B2B6B;"></div>';
    h += '<div style="width:' + o.draw + '%;background:#9CA3BF;"></div>';
    h += '<div style="width:' + o.away + '%;background:#C0392B;"></div>';
    h += '</div>';
    return h;
  }
};
if (typeof window !== 'undefined') window.Odds = Odds;

// ─── LOCAL STORAGE DB ────────────────────────────────────────────────────────
const DB = {
  key: (k) => `bolao_${k}`,

  // Store em MEMÓRIA (não persiste em localStorage). Tudo vem do Supabase a cada carregamento.
  // localStorage guarda só login (bolao_session/bolao_user) e a flag bolao_synced_<email>.
  _mem: {},
  get(k, def = null) { var v = this._mem[k]; return v === undefined ? def : v; },
  set(k, v) { this._mem[k] = v; },

  // Games
  getGames() { return this.get('games', DEFAULT_GAMES); },
  saveGames(g) { this.set('games', g); },

  // Bets
  getBets() { return this.get('bets', {}); },
  saveBets(b) { this.set('bets', b); },
  getUserBets(userId) { 
    const b = this.getBets(); 
    // Try email first (primary key), then userId, then email from Auth
    if (b[userId]) return b[userId];
    const email = Auth.user && Auth.user.email;
    if (email && b[email]) return b[email];
    // Also try looking up by matching any key that looks like an email
    const keys = Object.keys(b);
    for (var i = 0; i < keys.length; i++) {
      if (keys[i].includes('@') && Auth.user && (keys[i] === Auth.user.email)) return b[keys[i]];
    }
    return {};
  },
  saveBet(userId, gameId, bet) {
    const b = this.getBets();
    // Always use email as key for consistency with Supabase sync
    const key = (Auth.user && Auth.user.email) ? Auth.user.email : userId;
    if (!b[key]) b[key] = {};
    b[key][gameId] = { ...bet, savedAt: Date.now() };
    this.saveBets(b);
  },

  // Specials
  getSpecials() { return this.get('specials', {}); },
  getUserSpecials(userId) {
    const s = this.getSpecials();
    if (s[userId]) return s[userId];
    const email = Auth.user && Auth.user.email;
    if (email && s[email]) return s[email];
    return {};
  },
  saveSpecials(userId, data) {
    const s = this.getSpecials();
    // Always use email as key for consistency
    const key = (Auth.user && Auth.user.email) ? Auth.user.email : userId;
    s[key] = { ...data, savedAt: Date.now() };
    this.set('specials', s);
  },

  // Users
  getUsers() { return this.get('users', DEFAULT_USERS); },
  saveUsers(u) { this.set('users', u); },

  // Results (final Copa results)
  getFinalResults() { return this.get('final_results', null); },
  saveFinalResults(r) { this.set('final_results', r); },

  // Ranking
  getRanking() {
    // Calculado no servidor (RPC public.ranking) e cacheado por syncRankingFromSupabase.
    // Nunca usa palpite alheio cru no cliente.
    return this.get('ranking', []);
  }
};

