// ─── UTILS ───────────────────────────────────────────────────────────────────
const Utils = {
  formatDate(dateStr) {
    const d = new Date(dateStr);
    return d.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short' });
  },
  formatTime(dateStr) {
    return new Date(dateStr).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  },
  formatDateTime(dateStr) {
    const d = new Date(dateStr);
    return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) + ' ' +
           d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  },
  timeUntil(dateStr) {
    const diff = new Date(dateStr).getTime() - Date.now();
    if (diff <= 0) return null;
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    return { h, m, s, diff };
  },
  betDeadline(game) {
    return new Date(new Date(game.date).getTime() - 3600000);
  },
  formatCountdown(deadlineMs) {
    const diff = deadlineMs - Date.now();
    if (diff <= 0) return null;
    const d = Math.floor(diff / 86400000);
    const h = Math.floor((diff % 86400000) / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    if (d > 0) return 'Fecha em ' + d + 'd ' + h + 'h';
    if (h > 0) return 'Fecha em ' + h + 'h ' + m + 'min';
    if (m > 0) return 'Fecha em ' + m + 'min ' + s + 's';
    return 'Fecha em ' + s + 's';
  },
  canBet(game) {
    if (game.tbd || game.result) return false;
    return Date.now() < this.betDeadline(game).getTime();
  },
  phaseName(p) {
    return { groups:'Fase de Grupos', round_of_32:'16-avos de Final', round_of_16:'Oitavas de Final', quarterfinals:'Quartas de Final', semifinals:'Semifinais', third_place:'3º Lugar', final:'Final' }[p] || p;
  },
  phaseMultiplier(p) { return MULTIPLIERS[p] || 1; },

  toast(msg, type = 'info') {
    const c = document.getElementById('toastContainer');
    if (!c) return;
    const t = document.createElement('div');
    t.className = `toast ${type}`;
    t.innerHTML = `<span>${msg}</span>`;
    c.appendChild(t);
    setTimeout(() => t.classList.add('show'), 10);
    setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 3000);
  },

  initials(name) {
    return name.split(' ').slice(0,2).map(n => n[0]).join('').toUpperCase();
  },

  // Render sidebar & topbar
  renderShell(activeNav) {
    const user = Auth.user;
    const isAdmin = Auth.isAdmin();

    const navItems = [
      { id: 'dashboard', icon: '🏠', label: 'Dashboard', href: 'dashboard.html' },
      { id: 'palpites', icon: '⚽', label: 'Apostas', href: 'apostas.html', badge: null },
      { id: 'palpites', icon: '🎯', label: 'Palpites Especiais', href: 'palpites.html' },
      { id: 'ranking', icon: '🏆', label: 'Ranking', href: 'ranking.html' },
      { id: 'chaveamento', icon: '📋', label: 'Chaveamento', href: 'chaveamento.html' },
      { id: 'perfil', icon: '👤', label: 'Meu Perfil', href: 'perfil.html' },
      { id: 'hall', icon: '🌟', label: 'Hall da Fama', href: 'hall.html' },
    ];

    const adminNav = isAdmin ? `
      <div class="nav-section-label">Administração</div>
      <a class="nav-item ${activeNav==='admin'?'active':''}" href="admin.html"><span class="nav-icon">⚙️</span> Painel Admin</a>
    ` : '';

    const pendingBets = DB.getGames().filter(g => Utils.canBet(g) && !DB.getUserBets(user?.id || '')[g.id]).length;

    const sidebarHtml = `
    <aside class="sidebar" id="sidebar">
      <div class="sidebar-logo">
        <img src="../assets/porter-logo.png" alt="Porter" onerror="this.outerHTML='<span style=&quot;font-family:var(--font-display);font-size:1.5rem;font-weight:900;color:white;&quot;>PORTER</span>'"/>
      </div>
      <div class="sidebar-tournament">
        <div class="t-name">⚽ Bolão Oficial</div>
        <div class="t-year" style="color:white">Copa 2026</div>
        <div style="font-size:0.65rem;color:rgba(255,255,255,0.5);margin-top:2px;">Porter & Almah</div>
      </div>
      <nav class="sidebar-nav">
        <div class="nav-section-label">Menu Principal</div>
        ${navItems.map(item => `
          <a class="nav-item ${activeNav===item.id?'active':''}" href="${item.href}">
            <span class="nav-icon">${item.icon}</span>
            ${item.label}
            ${item.id==='palpites' && pendingBets > 0 ? `<span class="nav-badge">${pendingBets}</span>` : ''}
          </a>
        `).join('')}
        ${adminNav}
      </nav>
      <div class="sidebar-footer">
        <div class="sidebar-user">
          <div class="sidebar-avatar">${user?.initials||'?'}</div>
          <div class="sidebar-user-info">
            <div class="name">${user?.name||'Usuário'}</div>
            <div class="company">${user?.company||''}</div>
          </div>
        </div>
      </div>
    </aside>`;

    const topbarHtml = `
    <header class="topbar">
      <div class="topbar-left">
        <button class="topbar-btn menu-toggle" onclick="document.getElementById('sidebar').classList.toggle('open')">
          <span style="font-size:1.2rem">☰</span>
        </button>
        <span class="topbar-title">${navItems.find(n=>n.id===activeNav)?.label || (activeNav==='admin'?'Admin':'Bolão Copa 2026')}</span>
      </div>
      <div class="topbar-right">
        <button class="topbar-btn" onclick="window.location.href='apostas.html'" title="Apostas">
          <span>⚽</span>
          ${pendingBets > 0 ? '<span class="badge"></span>' : ''}
        </button>
        <button class="topbar-btn" title="Notificações"><span>🔔</span></button>
        <button class="topbar-btn" onclick="Auth.logout()" title="Sair"><span>🚪</span></button>
      </div>
    </header>`;

    document.body.insertAdjacentHTML('afterbegin', `<div class="app-layout">`);

    const appLayout = document.querySelector('.app-layout') || document.body;

    // Find main-content and wrap it
    const mainContent = document.querySelector('.main-content');
    if (mainContent) {
      appLayout.insertAdjacentHTML('afterbegin', sidebarHtml);
      mainContent.insertAdjacentHTML('afterbegin', topbarHtml);
    }
  }
};

// Live countdown ticker — updates all .bet-countdown spans every second
setInterval(function(){
  var els = document.querySelectorAll('.bet-countdown');
  for (var i = 0; i < els.length; i++) {
    var dl = parseInt(els[i].getAttribute('data-deadline'), 10);
    var txt = Utils.formatCountdown(dl);
    els[i].textContent = txt === null ? '🔒 Encerrado' : '⏰ ' + txt;
  }
}, 1000);

var SPA={
  pages:{},current:null,
  navigate:function(page){
    if(!page||!this.pages[page])page='login';
    var raw=localStorage.getItem('bolao_user'),user=raw?JSON.parse(raw):null;
    if(page!=='login'&&!user){this.navigate('login');return;}
    if(page==='admin'||page==='config'){
      // gate local (cosmético) + confirmação no servidor (localStorage é burlável)
      if(!user||user.role!=='admin'){this.navigate('dashboard');return;}
      Auth.verifyAdmin().then(function(ok){
        if(ok===false){ try{Utils.toast('Acesso negado: você não é administrador.','error');}catch(e){} Auth.logout(); }
      });
    }
    this.current=page;
    var se=document.getElementById('__ps__');
    if(!se){se=document.createElement('style');se.id='__ps__';document.head.appendChild(se);}
    se.textContent=this.pages[page].style||'';
    var tpl=document.getElementById('tpl-'+page),root=document.getElementById('spa-root');
    root.innerHTML=tpl?tpl.innerHTML:'';
    window.scrollTo(0,0);
    if(!document.getElementById('toastContainer')){var tc=document.createElement('div');tc.className='toast-container';tc.id='toastContainer';document.body.appendChild(tc);}
    if(page!=='login'){Auth.user=user;this._shell(page,user);}
    try{this.pages[page].script();}catch(e){console.error('[SPA]',page,e.message,e);}
    if(history.replaceState)history.replaceState(null,'','#'+page);
  },
  
  _shell: function(page, user) {
    var NAV=[
      {id:"dashboard",icon:"🏠",label:"Dashboard"},
      {id:"apostas",icon:"⚽",label:"Palpites"},
      {id:"apostas_dia",icon:"📋",label:"Palpites do Dia"},
      {id:"ranking",icon:"🏆",label:"Ranking"},
      {id:"resultados",icon:"🏟️",label:"Resultados"},
      {id:"palpites",icon:"🎯",label:"Palpites Especiais"},
      {id:"regras",icon:"📋",label:"Regras & Pontuação"},
      {id:"perfil",icon:"👤",label:"Meu Perfil"},
      {id:"hall",icon:"🌟",label:"Hall da Fama"}
    ];
    var pending=DB.getGames().filter(function(g){return Utils.canBet(g)&&!DB.getUserBets((user&&(user.id||user.email))||'')[g.id];}).length;
    var isAdmin=user&&user.role==='admin';
    var sb=document.getElementById('sidebar');
    if(sb){
      var h='';
      h+='<div class="sidebar-tournament"><div class="t-name">⚽ Bolão Oficial</div><div class="t-year" style="color:white">Copa 2026</div><div style="font-size:.65rem;color:rgba(255,255,255,.5);margin-top:2px">Porter & Almah</div></div>';
      h+='<nav class="sidebar-nav"><div class="nav-section-label">Menu Principal</div>';
      for(var i=0;i<NAV.length;i++){
        var n=NAV[i];
        h+='<a class="nav-item'+(page===n.id?' active':'')+'" data-nav="'+n.id+'" style="cursor:pointer"><span class="nav-icon">'+n.icon+'</span>'+n.label+(n.id==='palpites'&&pending>0?'<span class="nav-badge">'+pending+'</span>':'')+'</a>';
      }
      if(isAdmin){
        h+='<div class="nav-section-label">Administração</div>';
        h+='<a class="nav-item'+(page==='admin'?' active':'')+'" data-nav="admin" style="cursor:pointer"><span class="nav-icon">⚽</span> Gerenciar Jogos</a>';
        h+='<a class="nav-item'+(page==='config'?' active':'')+'" data-nav="config" style="cursor:pointer"><span class="nav-icon">⚙️</span> Configurações</a>';
      }
      h+='</nav><div class="sidebar-footer"><div class="sidebar-user"><div class="sidebar-avatar">'+(user.initials||'?')+'</div><div class="sidebar-user-info"><div class="name">'+(esc(user.name)||'')+'</div><div class="company">'+(esc(user.company)||'')+'</div></div></div></div>';
      sb.innerHTML=h;
      sb.addEventListener('click',function(e){var a=e.target.closest('[data-nav]');if(a)SPA.navigate(a.getAttribute('data-nav'));});
    }
    var LABELS={dashboard:'Dashboard',apostas:'Apostas','apostas_dia':'Palpites do Dia',ranking:'Ranking',palpites:'Palpites Especiais',regras:'Regras & Pontuação',chaveamento:'Chaveamento',perfil:'Meu Perfil',hall:'Hall da Fama',admin:'Gerenciar Jogos',config:'Configurações'};
    var tb=document.querySelector('.topbar');
    if(tb){
      var t='<div class="topbar-left"><button class="topbar-btn menu-toggle" data-action="togglesidebar"><span style="font-size:1.2rem">☰</span></button><span class="topbar-title">'+(LABELS[page]||'')+'</span></div><div class="topbar-right">';
      if(pending>0)t+='<button class="topbar-btn" data-nav="palpites"><span>⚽</span><span class="badge"></span></button>';
      if(isAdmin)t+='<button class="topbar-btn" data-nav="config"><span>⚙️</span></button>';
      t+='<button class="topbar-btn" data-action="logout" style="color:var(--porter-red)"><span>🚪</span></button></div>';
      tb.innerHTML=t;
      tb.addEventListener('click',function(e){
        var el=e.target.closest('[data-nav],[data-action]');if(!el)return;
        var nav=el.getAttribute('data-nav'),act=el.getAttribute('data-action');
        if(nav)SPA.navigate(nav);
        if(act==='logout')SPA.logout();
        if(act==='togglesidebar'){var s=document.getElementById('sidebar');if(s)s.classList.toggle('open');}
      });
    }
    // Fecha o menu mobile ao tocar fora (registrado uma vez)
    if(!window._sidebarOutsideClose){
      window._sidebarOutsideClose=true;
      document.addEventListener('click',function(e){
        var s=document.getElementById('sidebar');
        if(!s||!s.classList.contains('open'))return;
        if(e.target.closest('#sidebar')||e.target.closest('[data-action="togglesidebar"]'))return;
        s.classList.remove('open');
      });
    }
  }
,
  logout:function(){Sess.clear();this.navigate('login');}
};
